<template>
  <div>
    <div class="flex-interval">
      <div class="itemBox">
        <div>
          <div class="fs-14">CPU使用量</div>
          <div class="fs-25 mt-5">{{ operateData(dataObj.cpu_used) }}%</div>
          <div class="fs-12 mt-5">
            总量
            <span style="color: #13deb9; font-weight: 600">
              {{ operateData(dataObj.cpu_total) }}%</span
            >
          </div>
        </div>
        <div class="iconbox">
          <i class="icon iconf-cpu"></i>
        </div>
      </div>
      <div class="itemBox">
        <div>
          <div class="fs-14">NPU使用量</div>
          <div class="fs-25 mt-5">{{ operateData(dataObj.npu_used) }}%</div>
          <div class="fs-12 mt-5">
            总量
            <span style="color: #13deb9; font-weight: 600">
              {{ operateData(dataObj.npu_total) }}%</span
            >
          </div>
        </div>
        <div class="iconbox">
          <i class="icon iconf-cpu"></i>
        </div>
      </div>

      <div class="itemBox">
        <div>
          <div class="fs-14">内存使用量</div>
          <div class="fs-25 mt-5">{{ operateData(dataObj.mem_used) }}G</div>
          <div class="fs-12 mt-5">
            总量
            <span style="color: #13deb9; font-weight: 600"
              >{{ operateData(dataObj.mem_total) }}G</span
            >
          </div>
        </div>
        <div class="iconbox">
          <i class="icon iconf-mem"></i>
        </div>
      </div>
      <div class="itemBox">
        <div>
          <div class="fs-14">磁盘使用量</div>
          <div class="fs-25 mt-5">{{ operateData(dataObj.disk_used) }}G</div>
          <div class="fs-12 mt-5">
            总量
            <span style="color: #13deb9; font-weight: 600"
              >{{ operateData(dataObj.disk_total) }}G</span
            >
          </div>
        </div>
        <div class="iconbox">
          <i class="icon iconf-deck"></i>
        </div>
      </div>
    </div>
    <div class="flex-interval mt-10 charts">
      <LineChars :dataList="dataList" :chartsObj="chartsObj"></LineChars>
    </div>
  </div>
</template>

<script>
import LineChars from "@/components/lineChars.vue";
import { formatStamp } from "@/assets/utils/config";
export default {
  components: {
    LineChars,
  },
  data() {
    return {
      dataList: [
        {
          name: "CPU利用率",
          valueList: [],
          color: "#7a6de3",
          type: "cpu",
        },
        {
          name: "NPU利用率",
          valueList: [],
          color: "#24aaff",
          type: "npu",
        },
        {
          name: "内存利用率",
          valueList: [],
          color: "#13deb9",
          type: "mem",
        },
      ],
      timer: null,
      dataObj: {},
      chartsObj: {
        xData: [],
      },
    };
  },
  computed: {},
  created() {
    this.getData();
    this.startPolling();
  },
  mounted() {
    this.setStyle();
  },
  methods: {
    operateData(val) {
      return val ? Number(val.toFixed(2)) : 0;
    },
    startPolling() {
      this.timer = setInterval(this.getData, 3000);
    },
    getData() {
      this.$api.get(`/statistics/getServerStatistics`).then((res) => {
        this.dataObj = res.data.data;
        this.dataList.forEach((item) => {
          const usedKey = `${item.type}_used`;
          if (this.dataObj[usedKey] !== undefined) {
            let value = this.dataObj[usedKey];
            if (item.type == "mem") {
              value = this.operateData(
                (this.dataObj.mem_used / this.dataObj.mem_total) * 100
              );
            } else {
              value = Number(value.toFixed(2));
            }
            item.valueList.push(value);
            if (item.valueList.length > 8) {
              item.valueList.shift();
            }
          }
        });
        this.chartsObj.xData.push(formatStamp(+new Date(), "hh:mm:ss"));
        if (this.chartsObj.xData.length > 8) {
          this.chartsObj.xData.shift();
        }
      });
    },
    setStyle() {
      const elMain = document.querySelector(".el-main");
      if (elMain) {
        elMain.style.padding = "0px";
        elMain.style.overflow = "hidden";
        elMain.style.background = "none";
        elMain.style.border = "none";
      }
    },
  },
  beforeDestroy() {
    if (this.timer) {
      clearInterval(this.timer); //关闭
      this.timer = null;
    }
    const elMain = document.querySelector(".el-main");
    if (elMain) {
      elMain.style.padding = "20px";
      elMain.style.overflow = "auto";
      elMain.style.background = "#fff";
      elMain.style.border = "1px solid #dbdfe999";
    }
  },
};
</script>

